import{_ as s,C as a,o as i,c as n,j as t,a as r,E as c,ag as d}from"./chunks/framework.DMVuHR7L.js";const w=JSON.parse('{"title":"Screen Mirror","description":"","frontmatter":{},"headers":[],"relativePath":"features/screen-mirror.md","filePath":"features/screen-mirror.md","lastUpdated":1779995066000}'),l={name:"features/screen-mirror.md"};function h(p,e,u,g,m,f){const o=a("ThemeImage");return i(),n("div",null,[e[0]||(e[0]=t("h1",{id:"screen-mirror",tabindex:"-1"},[r("Screen Mirror "),t("a",{class:"header-anchor",href:"#screen-mirror","aria-label":'Permalink to "Screen Mirror"'},"​")],-1)),e[1]||(e[1]=t("p",null,[r("The Screen Mirror widget is a scrcpy-style live screen of the device, decoded in the browser via "),t("strong",null,"WebCodecs"),r(". It's capped at one instance per dashboard so two Mirror tiles can't fight for the same H.264 stream.")],-1)),c(o,{"src-dark":"/img/features/mirror-default.png","src-light":"/img/features/mirror-default-light.png",alt:"Screen Mirror tile"}),e[2]||(e[2]=d('<h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>WebLogcat ships a copy of <code>scrcpy-server-v2.7.jar</code> and pushes it to the device on connect. The server captures the screen and streams an H.264 NAL stream back over the ADB transport; the widget decodes it using the <code>@yume-chan/scrcpy-decoder-webcodecs</code> decoder and renders the frames to a <code>&lt;canvas&gt;</code>.</p><p>Latency is roughly 50–150 ms over USB on a Pixel — not as tight as a native <code>scrcpy</code>, but indistinguishable for non-game use.</p><h2 id="interaction" tabindex="-1">Interaction <a class="header-anchor" href="#interaction" aria-label="Permalink to &quot;Interaction&quot;">​</a></h2><ul><li><strong>Tap, drag, swipe.</strong> Click on the canvas to send tap events. Drag to swipe. Multi-touch is mapped from <code>touch</code> events on touchscreens; on a laptop, click counts as a single touch.</li><li><strong>Hardware buttons.</strong> The bezel renders the standard Android buttons — Back, Home, Recents — plus power, volume up/down, rotate, screenshot, and record.</li><li><strong>Type into the device.</strong> Click the canvas first to focus, then type. Backspace, Enter, Tab, arrows and Escape are forwarded as the matching Android keycodes — they no longer leak into the dashboard-level &quot;delete the focused tile&quot; shortcut while the mirror is focused.</li><li><strong>Clipboard sync.</strong> With the mirror focused, <strong>Ctrl/Cmd+V</strong> pastes the host&#39;s clipboard into the device&#39;s foreground text field. <strong>Ctrl/Cmd+C</strong> forwards Ctrl+C to the device (which copies the current selection in the foreground app), waits for scrcpy&#39;s clipboard auto-sync to report the new value, then writes it to the host clipboard. If nothing is selected on the device, falls back to whatever was last on the device clipboard. Both operations need the browser&#39;s Clipboard permission, granted automatically on user activation in a focused tab; a toast surfaces a denial if the browser blocks it.</li><li><strong>Text-editing shortcuts.</strong> Mac-standard cursor and selection keys are forwarded to the device&#39;s foreground text field: <ul><li><strong>⌘+A</strong> — select all (forwarded as Ctrl+A; the browser&#39;s own <em>select all</em> is suppressed while the mirror has focus).</li><li><strong>⇧+arrow</strong> — extend selection by character / line.</li><li><strong>⌘+←/→</strong> — move to start / end of line.</li><li><strong>⌘+↑/↓</strong> — move to start / end of document.</li><li><strong>⌘+⇧+arrow</strong> — same as the ⌘ shortcuts but extending the selection instead of moving the cursor.</li><li><strong>⌥+←/→</strong> — move by word (add ⇧ to extend selection).</li></ul></li></ul><h2 id="open-files-on-device" tabindex="-1">Open files on device <a class="header-anchor" href="#open-files-on-device" aria-label="Permalink to &quot;Open files on device&quot;">​</a></h2><p>Drop a file onto the Mirror surface to open it on the device. Two sources are accepted:</p><ul><li><strong>Files widget rows.</strong> Already live on the device — the drop just triggers the open.</li><li><strong>Host OS files (Finder / Explorer / browser downloads).</strong> Pushed to <code>/sdcard/Download/&lt;name&gt;</code> first via the ADB sync protocol, then opened.</li></ul><p>In either case the open mechanism is the same:</p><ul><li><code>.apk</code> files are installed via <code>pm install -r</code> (staged through <code>/data/local/tmp</code> so SELinux is happy on Android 14+).</li><li>Anything else fires an <code>am start VIEW</code> intent with the file&#39;s MIME type, letting the device pick a viewer (PDF, image, video, …).</li></ul><p>A &quot;Drop to open on device&quot; overlay appears while the drag is over the widget. A toast confirms success or surfaces the failure reason.</p><h2 id="recording" tabindex="-1">Recording <a class="header-anchor" href="#recording" aria-label="Permalink to &quot;Recording&quot;">​</a></h2><p>The record button starts an MP4 capture of the live stream — encoded with <code>mp4-muxer</code> directly in the browser, no server round-trip. The recording icon turns red while it&#39;s running; click it again to stop. The MP4 is saved to your downloads folder.</p><h2 id="screenshot" tabindex="-1">Screenshot <a class="header-anchor" href="#screenshot" aria-label="Permalink to &quot;Screenshot&quot;">​</a></h2><p>The camera icon writes the current frame as a PNG to your downloads folder. Lossless, full device resolution.</p><h2 id="per-widget-settings" tabindex="-1">Per-widget settings <a class="header-anchor" href="#per-widget-settings" aria-label="Permalink to &quot;Per-widget settings&quot;">​</a></h2><ul><li><strong>Overlay font size.</strong> Affects the per-frame stats overlay (toggled via the eye icon).</li><li><strong>Bitrate cap.</strong> Trade quality vs. bandwidth. Defaults to 8 Mbps.</li><li><strong>Display rotation.</strong> Force portrait, landscape, or auto.</li></ul><h2 id="compatibility" tabindex="-1">Compatibility <a class="header-anchor" href="#compatibility" aria-label="Permalink to &quot;Compatibility&quot;">​</a></h2><ul><li>Mirror needs a Chromium build with <strong>WebCodecs</strong> (Chrome / Edge 94+). Older browsers fall back to a <em>not supported</em> notice.</li><li>The device needs to be modern enough to run the bundled scrcpy server (Android 7+ in practice).</li><li>Some manufacturers block screen capture from certain apps (banking, DRM-protected video). Those frames render black — that&#39;s the device, not WebLogcat.</li></ul>',19))])}const v=s(l,[["render",h]]);export{w as __pageData,v as default};
